<script lang="ts">import AcademicEmptyState from '$lib/components/academic/AcademicEmptyState.svelte'; import AcademicErrorState from '$lib/components/academic/AcademicErrorState.svelte'; import ConsultationSchedule from '$lib/components/faculty/ConsultationSchedule.svelte'; import PageHeader from '$lib/components/shell/PageHeader.svelte'; let { data } = $props(); function groupByFaculty(items:typeof data.items){const groups=new Map<string,typeof data.items>();for(const item of items){const current=groups.get(item.facultyName)??[];current.push(item);groups.set(item.facultyName,current);}return [...groups.entries()];} const dayOptions=[['','All days'],['1','Monday'],['2','Tuesday'],['3','Wednesday'],['4','Thursday'],['5','Friday'],['6','Saturday']];</script>
<svelte:head><title>Consultations · IMS Academic Hub</title></svelte:head>
<div class="mx-auto grid w-full max-w-[1180px] gap-7 px-4 py-7 sm:px-6 sm:py-9"><PageHeader eyebrow="Consultations" title="Find scheduled faculty consultation hours." description="Schedules are term-specific and verified. They describe planned availability—not live faculty location." />
<form class="grid gap-2 border border-line-strong bg-white p-2 sm:grid-cols-[minmax(14rem,22rem)_auto]" method="GET"><label><span class="sr-only">Day</span><select class="min-h-12 w-full border border-line-strong bg-white px-3 text-ink" name="day">{#each dayOptions as option}<option value={option[0]} selected={String(data.weekday??'')===option[0]}>{option[1]}</option>{/each}</select></label><button class="min-h-12 bg-ims-blue-deep px-4 font-bold text-white" type="submit">Apply Filter</button></form>
<section class="grid gap-4" aria-labelledby="consultation-results-title"><header class="flex items-end justify-between border-b border-line pb-3"><div><p class="font-mono text-xs font-semibold uppercase tracking-[.12em] text-ims-blue-ink">Published schedule</p><h2 class="text-2xl font-semibold" id="consultation-results-title">Consultation hours</h2></div>{#if data.items.length}<span class="font-mono text-xs text-muted">{data.items.length} result{data.items.length===1?'':'s'}</span>{/if}</header>
{#if !data.repositoryStatus.configured}<AcademicEmptyState title="Consultation data is not connected yet" message="The app is ready for current-term consultation data, but no repository is configured." />{:else if !data.repositoryStatus.available}<AcademicErrorState message={data.repositoryStatus.message}/>{:else if data.items.length===0}<AcademicEmptyState title="No published consultation hours" message="No verified consultation records match this view for the current term." />{:else}<div class="grid gap-4 lg:grid-cols-2">{#each groupByFaculty(data.items) as [facultyName,items]}<section class="grid content-start gap-3 border border-line-strong bg-white p-4"><header class="flex items-center justify-between gap-3"><div><p class="font-mono text-xs font-semibold uppercase tracking-[.12em] text-ims-blue-ink">Faculty</p><h3 class="text-xl font-semibold">{facultyName}</h3></div>{#if items?.[0]}<a class="min-h-11 px-2 py-3 font-bold text-ims-blue-ink" href={`/faculty/${items[0].facultySlug}`}>Profile →</a>{/if}</header>{#if items}<ConsultationSchedule {items}/>{/if}</section>{/each}</div>{/if}</section></div>
